\begin{array}{c|l}
\textbf{statement} \amp \textbf{meaning}\\
\hline
s(t)>0 \amp \text{the object is on the positive side of the origin}\\
s(t)<0 \amp \text{the object is on the negative side of the origin}\\
v(t)>0 \amp \text{the object is moving in the positive direction}\\
v(t)<0 \amp \text{the object is moving in the negative direction}\\
a(t)>0 \amp \text{the velocity is increasing}\\
a(t)<0 \amp \text{the velocity is decreasing}
\end{array}

\begin{array}{c|c|c}
\textbf{velocity} \amp \textbf{acceleration} \amp \textbf{speed}\\
\hline
v>0 \amp a>0 \amp \text{increasing}\\
v>0 \amp a<0 \amp \text{decreasing}\\
v<0 \amp a>0 \amp \text{decreasing}\\
v<0 \amp a<0 \amp \text{increasing}
\end{array}

\begin{array}{ll}
1. \amp \text{Choose an origin and a positive direction.}\\
2. \amp \text{Write the position function with units.}\\
3. \amp \text{Differentiate once for velocity.}\\
4. \amp \text{Differentiate twice for acceleration.}\\
5. \amp \text{Use \(|v(t)|\) when the question asks for speed.}
\end{array}
